-- =============================================================================
-- 心飞健康 业务字典种子（幂等，可重复执行）
-- 依据：docs/requirements/12-系统设置.md §3.3~§3.11（全量 76 型 / 311 条值）
-- 规则：12 §3.1 —— 值域与功能文档逐字一致；remark 写「出处 + 消费模块」；
--       dict_id 从 100 起、dict_code 每型预留 20 个号段（现库框架 max dict_id=12、dict_code=38，无冲突）
-- 实测（192.168.20.130/xfjk，MySQL 8.0.46）：
--   sys_dict_type  PK=dict_id（无自增，必须显式给值）；UNIQUE KEY (tenant_id, dict_type) ⇒ 型表可用 ON DUPLICATE KEY UPDATE
--   sys_dict_data  PK=dict_code（无自增）；**无 (dict_type, dict_value) 唯一索引** ⇒ 只能按 dict_type 先删后插（12 §11）
--   两表均**无 status 列**（12 §2），停用只能删行，禁止在 INSERT 里写 status
--   tenant_id 默认 '000000'，与框架现存 10 型一致，本脚本不显式写
-- is_default：全表仅 health_notify_way 的「电话+系统推送」取 'Y'（12 §3.6 注「默认第三种」），其余 'N'
-- list_class/css_class：文档未规定 → 一律留 NULL，展示色由前端按值域自行映射，禁止据字典标签做业务判断（12 §3.1 第 4 条）
-- 安全：本脚本只触碰 dict_type LIKE 'health\_%' 的行；框架 sys_* 型不受影响；禁止在生产库执行（04 §7、红线）
-- =============================================================================

-- 0. 执行前自检：期望 0 行。命中 = 库里存在本清单之外的 health_ 型（历史遗留或文档未登记），
--    必须先回 12 §3 补登记再重跑，禁止让未登记的型继续留在库里
SELECT dict_id, dict_type, dict_name FROM sys_dict_type
 WHERE dict_type LIKE 'health\_%'
   AND dict_type NOT IN ('health_flow_status', 'health_order_status', 'health_order_type', 'health_item_status', 'health_report_status', 'health_batch_status', 'health_batchmember_status', 'health_override_status', 'health_publish_status', 'health_article_status', 'health_plan_status', 'health_followupplan_status', 'health_task_status', 'health_record_status', 'health_result_type', 'health_abnormal_flag', 'health_qualitative', 'health_abnormal_grade', 'health_specimen', 'health_checkitem_type', 'health_sex_scope', 'health_physio_state', 'health_edge_flag', 'health_major_positive', 'health_forbid_scope', 'health_forbid_action', 'health_forbid_cond_key', 'health_import_mode', 'health_grouprule_field', 'health_marital_status', 'health_sex_history', 'health_pregnancy_status', 'health_flag_yn', 'health_blood_type', 'health_bind_source', 'health_archive_type', 'health_report_source', 'health_notify_way', 'health_export_mask', 'health_questionnaire_category', 'health_scale_type', 'health_question_type', 'health_scale_rule_type', 'health_level_code', 'health_severity', 'health_suggestion_type', 'health_indicator_value_type', 'health_crowd_source_type', 'health_compare_operator', 'health_logic_op', 'health_config_value_type', 'health_assessment_source', 'health_item_type', 'health_follow_way', 'health_symptom', 'health_salt_intake', 'health_psych_adjust', 'health_medical_compliance', 'health_medicine_adherence', 'health_adverse_reaction', 'health_visit_classify', 'health_exercise_type', 'health_exercise_intensity', 'health_diet_type', 'health_disease_type', 'health_plan_category', 'health_conclusion_type', 'health_advice_type', 'health_advice_target', 'health_dict_relation', 'health_kb_rule_action', 'health_total_conclusion', 'health_report_type', 'health_workload_caliber', 'health_qc_rate_type', 'health_stat_period');

-- 1. 字典类型（ON DUPLICATE KEY UPDATE 依赖 UNIQUE (tenant_id, dict_type)）
ON DUPLICATE KEY UPDATE `dict_name`=VALUES(`dict_name`), `remark`=VALUES(`remark`), `update_by`=1, `update_time`=NOW();

-- 2. 字典数据（先按 health 前缀清理，再整批重插；禁止无 WHERE 全表删除）
DELETE FROM `sys_dict_data` WHERE `dict_type` LIKE 'health\_%';


-- 3. 回查（期望：type_cnt=76，data_cnt=311，无 is_default='Y' 之外的默认项）
SELECT COUNT(*) AS type_cnt FROM sys_dict_type WHERE dict_type LIKE 'health\_%';
SELECT COUNT(*) AS data_cnt FROM sys_dict_data WHERE dict_type LIKE 'health\_%';
SELECT COUNT(*) AS default_cnt FROM sys_dict_data WHERE dict_type LIKE 'health\_%' AND is_default='Y';
SELECT dict_type, COUNT(*) AS n FROM sys_dict_data WHERE dict_type LIKE 'health\_%' GROUP BY dict_type HAVING n=0;
